function querylatlngdByID(idArr) {
    let tmpArr = [];

    for (let i = 0; i < idArr.length; i++) {
        let rawId = idArr[i].trim();
        let searchId = "";
        let db = "";

        // 1. 識別與清洗 ID
        // 邏輯順序：優先處理 kplace 防止被 pl 誤判
        if (rawId.toLowerCase().includes("kplace") || rawId.toLowerCase().includes("koreanplace")) {
            searchId = rawId.replace(/kplace_|koreanplace_/gi, "");
            db = kplace;
        } else if (rawId.indexOf("hvd_") >= 0) {
            searchId = rawId.replace("hvd_", "");
            db = chgis;
        } else if (rawId.indexOf("twgis_") >= 0) {
            searchId = rawId.replace("twgis_", "");
            db = twgis;
        } else if (rawId.toLowerCase().startsWith("pl")) {
            searchId = parseInt(rawId.toLowerCase().replace("pl", ""), 10).toString();
            db = (typeof pl !== 'undefined') ? pl : ""; 
        }

        // 2. 匹配座標
        let patt = ";" + searchId + ",(-?\\d+(?:\\.\\d+)?),\\s*(-?\\d+(?:\\.\\d+)?)";
        let regex = new RegExp(patt); 
        let match = regex.exec(db);

        let lat = "0";
        let lng = "0";

        if (match != null) {
            lng = match[1]; // 經度
            lat = match[2]; // 緯度
        }
        
        tmpArr.push(lat + " " + lng);
    }
    return tmpArr;
}

